      "category": "polarity",
      "components": ["D7"],
      "pins": ["D7.1", "D7.2"],
      "nets": ["+12V", "GND"],
      "observed": "D7 anode (pin 2) is connected to +12V and cathode (pin 1) is connected to GND, forward-biasing the diode across the 12V input.",
      "expected": "D7 cathode (pin 1) should be connected to +12V and anode (pin 2) to GND, so the diode is reverse-biased under normal positive 12V supply and only conducts on reverse polarity.",
      "evidence": [
        {
          "source": "netlist",
          "quote": "(node (ref \"D7\") (pin \"2\") (pinfunction \"A\") (pintype \"passive\"))"
        },
        {
          "source": "netlist",
          "quote": "(node (ref \"D7\") (pin \"1\") (pinfunction \"K\") (pintype \"passive\"))"
        },
        {
          "source": "spec",
          "quote": "D7's cathode (K, pin 1) is tied to +12V and its anode (A, pin 2) is tied to GND."
        }
      ],
      "impact": "The diode will conduct heavily, shorting the 12V rail to ground, preventing the board from powering up and potentially damaging the diode or supply.",
      "confidence": 1.0
    }
  ],
  "summary": "The design files contain a polarity error on D7: the reverse-polarity protection diode is installed backwards, forward-biasing it across the 12V input and shorting the rail to ground."
}

